<?php
require __DIR__.'/includes/cms.php';
$categories = ac_categories(); $articles = ac_articles();
$q = trim((string) ($_GET['q'] ?? '')); $categorySlug = trim((string) ($_GET['category'] ?? '')); $month = trim((string) ($_GET['month'] ?? '')); $year = trim((string) ($_GET['year'] ?? ''));
$articles = array_values(array_filter($articles, function ($story) use ($q, $categorySlug, $month, $year) {
    $haystack = strtolower((string) ($story['title'] ?? '').' '.(string) ($story['summary'] ?? '').' '.(string) ($story['category']['name'] ?? ''));
    $date = strtotime((string) ($story['published_at'] ?? '')) ?: 0;
    return (!$q || str_contains($haystack, strtolower($q))) && (!$categorySlug || (string) ($story['category']['slug'] ?? '') === $categorySlug) && (!$month || ($date && date('m', $date) === $month)) && (!$year || ($date && date('Y', $date) === $year));
}));
$pageTitle = 'News archive'; require __DIR__.'/includes/head.php'; require __DIR__.'/includes/header.php';
?>
<main class="container"><header class="page-intro"><div class="eyebrow">African Chronicle</div><h1>News archive</h1><p>Find published stories by keyword, section or publication month.</p></header>
<form class="archive-tools" action="archive.php" method="get"><input name="q" type="search" value="<?= ac_e($q) ?>" placeholder="Search stories, authors or topics" aria-label="Search archive"><select name="category" aria-label="Filter by section"><option value="">All sections</option><?php foreach ($categories as $item): ?><option value="<?= ac_e($item['slug'] ?? '') ?>" <?= $categorySlug === (string) ($item['slug'] ?? '') ? 'selected' : '' ?>><?= ac_e($item['name'] ?? '') ?></option><?php endforeach ?></select><select name="month" aria-label="Filter by month"><option value="">All months</option><?php foreach (range(1, 12) as $number): ?><option value="<?= sprintf('%02d', $number) ?>" <?= $month === sprintf('%02d', $number) ? 'selected' : '' ?>><?= date('F', mktime(0, 0, 0, $number, 1)) ?></option><?php endforeach ?></select><select name="year" aria-label="Publication year"><option value="">All years</option><?php foreach (array_unique(array_filter(array_map(fn ($story) => substr((string) ($story['published_at'] ?? ''), 0, 4), $articles))) as $publishedYear): ?><option value="<?= ac_e($publishedYear) ?>" <?= $year === (string) $publishedYear ? 'selected' : '' ?>><?= ac_e($publishedYear) ?></option><?php endforeach ?></select><button class="button">Search archive</button></form>
<div class="section-layout"><section><h2 class="section-heading">Published stories</h2><div class="archive-results"><?php foreach ($articles as $story): ?><article class="archive-row"><div class="eyebrow"><?= ac_e(ac_category_name($story)) ?></div><h2><a href="<?= ac_e(ac_article_url($story)) ?>"><?= ac_e($story['title'] ?? '') ?></a></h2><p><?= ac_e($story['summary'] ?? '') ?></p><div class="meta"><?= ac_e(ac_date($story)) ?></div></article><?php endforeach ?><?php if (!$articles): ?><div class="empty-state">No published stories match these filters.</div><?php endif ?></div></section><aside><div class="sidebar-block"><h2>Previous editions</h2><p class="notice">Digital newspaper editions will appear here as they are uploaded by the newsroom.</p></div></aside></div></main>
<?php require __DIR__.'/includes/footer.php'; ?>
